<?phpif (!defined('BASEPATH'))    exit('No direct script access allowed');class do_order extends CI_Controller{    var $m_language = '';    var $m_nid_user_login = '';    var $m_nid = '';    var $m_event = '';    var $m_button_click = '';    var $m_link_page = '';    var $m_link_cancel = '';    var $m_form_title = '';    var $m_hidden_image_old = '';    var $cadmin_note = '';	var $cship = '';	var $cvat = '';	var $cprice_sale_vnd = '';	var $caddress = '';	var $cfullname = '';	var $nphone = '';	var $cmst = '';	var $cnote = '';    var $m_txt_nid = '';    var $m_cbo_order_status = '';    var $m_obj_order_status_view = '';	var $m_cbo_order_status_tt = '';    var $m_obj_order_status_tt_view = '';	var $m_cbo_order_status_vc = '';    var $m_obj_order_status_vc_view = '';    var $m_obj_order_view = '';    var $m_obj_data_view = '';    var $m_error_msg = '';    var $m_link_cancel_trans = '';    function __construct()    {        parent::__construct();        session_start();        $this->load->database();        $this->load->helper('ap_db');        $this->load->helper('ap_function');        $this->load->helper('ap_html');        $this->load->helper('ap_view');        $this->load->helper('ap_object');        $this->load->helper('ap_fck');        $this->tokaban_system_check = '1';        $this->load->model('order_model');    }    private function m_language_key($str_key)    {        return $this->lang->line('lbl.order.' . $str_key);    }    private function f_set_cookie($cookie_name, $cookie_value)    {        return dbset_cookie('cookie_order_' . $cookie_name, $cookie_value);    }    private function f_get_cookie($cookie_name)    {        return dbget_cookie('cookie_order_' . $cookie_name);    }    function f_edit($nid)    {        $this->m_event = 'edit';        $this->m_nid   = $nid;        $this->do_process();    }	function f_edit2($nid)    {        $this->m_event = 'edit2';        $this->m_nid   = $nid;        $this->do_process();    }    function f_update_edit()    {        $this->m_event = 'update_edit';        $this->do_process();    }    function f_add()    {        $this->m_event = 'add';        $this->m_nid   = '0';        $this->do_process();    }    function f_update_add()    {        $this->m_event = 'update_add';        $this->do_process();    }    function do_process()    {        $this->get_data();        $this->caculate_data();        $this->do_business();        $this->destroy_data();    }    private function get_data()    {        $this->m_nid_user_login = Fget_userdata('session_nid_user');        $this->m_language       = Fget_userdata('session_user_language');        $this->load->language('ap', $this->m_language);        if (isset($_POST['cbo_order_status']))            $this->m_cbo_order_status = $_POST['cbo_order_status'];		if (isset($_POST['cbo_order_status_tt']))            $this->m_cbo_order_status_tt = $_POST['cbo_order_status_tt'];		if (isset($_POST['cbo_order_status_vc']))            $this->m_cbo_order_status_vc = $_POST['cbo_order_status_vc'];        if (isset($_POST['hidden_nid']))            $this->m_nid = $_POST['hidden_nid'];        if (isset($_POST['hidden_event']))            $this->m_event = $_POST['hidden_event'];        if (isset($_POST['cadmin_note']))            $this->cadmin_note = $_POST['cadmin_note'];		if (isset($_POST['cship']))            $this->cship = $_POST['cship'];		if (isset($_POST['cvat']))            $this->cvat = $_POST['cvat'];		if (isset($_POST['cprice_sale_vnd']))            $this->cprice_sale_vnd = $_POST['cprice_sale_vnd'];		if (isset($_POST['caddress']))            $this->caddress = $_POST['caddress'];		if (isset($_POST['cfullname']))            $this->cfullname = $_POST['cfullname'];		if (isset($_POST['nphone']))            $this->nphone = $_POST['nphone'];		if (isset($_POST['cmst']))            $this->cmst = $_POST['cmst'];		if (isset($_POST['cnote']))            $this->cnote = $_POST['cnote'];        if (isset($_POST['hidden_button']))            $this->m_button_click = $_POST['hidden_button'];    }    private function caculate_data()    {        $this->m_link_page             = base_url() . 'index.php/do_order/f_update_edit';        $this->m_link_cancel           = base_url() . 'index.php/do_order_listview';        $this->m_obj_order_status_view = Obj_get_order_status_list($this->m_nid_user_login);		//$this->m_obj_order_status_tt_view = Obj_get_order_status_tt_list($this->m_nid_user_login);		//$this->m_obj_order_status_vc_view = Obj_get_order_status_vc_list($this->m_nid_user_login);        switch ($this->m_event) {            case 'edit':                $this->m_form_title       = $this->m_language_key('FormEditTitle');                $this->m_link_page        = base_url() . 'index.php/do_order/f_update_edit';                $this->m_obj_order_view   = $this->order_model->get_byid($this->m_nid);                $this->m_cbo_order_status = $this->m_obj_order_view['nid_order_status'];//				$this->m_cbo_order_status_tt = $this->m_obj_order_view['nid_order_status_tt'];//				$this->m_cbo_order_status_vc = $this->m_obj_order_view['nid_order_status_vc'];                $this->cadmin_note        = $this->m_obj_order_view['cadmin_note'];//				$this->cship        = $this->m_obj_order_view['cship'];//				$this->cvat        = $this->m_obj_order_view['cvat'];//				$this->cprice_sale_vnd        = $this->m_obj_order_view['cprice_sale_vnd'];				$this->caddress        = $this->m_obj_order_view['caddress'];				$this->cfullname        = $this->m_obj_order_view['cfullname'];				$this->nphone        = $this->m_obj_order_view['nphone'];//				$this->cmst        = $this->m_obj_order_view['cmst'];				$this->cnote        = $this->m_obj_order_view['cnote'];                $this->m_event            = 'update_edit';                break;			case 'edit2':                $this->m_form_title       = $this->m_language_key('FormEditTitle');                $this->m_link_page        = base_url() . 'index.php/do_order/f_update_edit';                $this->m_obj_order_view   = $this->order_model->get_byid($this->m_nid);                $this->m_cbo_order_status = $this->m_obj_order_view['nid_order_status'];				$this->m_cbo_order_status_tt = $this->m_obj_order_view['nid_order_status_tt'];				$this->m_cbo_order_status_vc = $this->m_obj_order_view['nid_order_status_vc'];                $this->cadmin_note        = $this->m_obj_order_view['cadmin_note'];				$this->cship        = $this->m_obj_order_view['cship'];				$this->cvat        = $this->m_obj_order_view['cvat'];				$this->cprice_sale_vnd        = $this->m_obj_order_view['cprice_sale_vnd'];				$this->caddress        = $this->m_obj_order_view['caddress'];				$this->cfullname        = $this->m_obj_order_view['cfullname'];				$this->nphone        = $this->m_obj_order_view['nphone'];				$this->cmst        = $this->m_obj_order_view['cmst'];				$this->cnote        = $this->m_obj_order_view['cnote'];                $this->m_event            = 'update_edit2';                break;	            case 'update_edit':                $this->m_form_title = $this->m_language_key('FormEditTitle');                if ($this->m_button_click == 'btn_submit')                    if ($this->update_data() == TRUE)                        redirect('do_order_listview');                $this->m_link_page = base_url() . 'index.php/do_order/f_update_edit';                break;			case 'update_edit2':                $this->m_form_title = $this->m_language_key('FormEditTitle');                if ($this->m_button_click == 'btn_submit')                    if ($this->update_data() == TRUE)                        redirect('do_order_listview');                $this->m_link_page = base_url() . 'index.php/do_order/f_update_edit';                break;	        }    }    private function do_business()    {        $data['event']               = $this->m_event;        $data['menu']                = Fget_menu_html($this->m_nid_user_login);        $data['lbl_form_title']      = $this->m_form_title;        $data['link_page']           = $this->m_link_page;        $data['link_cancel']         = $this->m_link_cancel;        $data['link_cancel_trans']   = $this->m_link_cancel_trans;        $data['cadmin_note']         = $this->cadmin_note;		$data['cship']         = $this->cship;		$data['cvat']         = $this->cvat;		$data['cprice_sale_vnd']         = $this->cprice_sale_vnd;		$data['caddress']         = $this->caddress;		$data['cfullname']         = $this->cfullname;		$data['nphone']         = $this->nphone;		$data['cmst']         = $this->cmst;		$data['cnote']         = $this->cnote;        $data['btn_update']          = $this->lang->line('btn.0000.Update');        $data['btn_cancel']          = $this->lang->line('btn.0000.Cancel');        $data['get_icon_notnull']    = Fget_icon_notnull();        $data['get_message_notnull'] = Fget_icon_notnull() . $this->lang->line('msg.0000.NotNullValue');        ;        $data['lbl_form_title']           = $this->m_form_title;        $data['lbl_ccode']                = $this->m_language_key('ccode');        $data['lbl_cfullname']            = $this->m_language_key('cfullname');        $data['lbl_cemail']               = $this->m_language_key('cemail');        $data['lbl_nphone']               = $this->m_language_key('nphone');        $data['lbl_caddress']             = $this->m_language_key('caddress');        $data['lbl_cnote']                = $this->m_language_key('cnote');        $data['lbl_nid_order_status']     = $this->m_language_key('nid_order_status');        $data['lbl_date01']               = $this->m_language_key('date01');        $data['lbl_date02']               = $this->m_language_key('date02');        $data['lbl_order_infomation']     = $this->m_language_key('order_infomation');        $data['lbl_product_infomation']   = $this->m_language_key('product_infomation');        $data['lbl_error_msg']            = $this->m_error_msg;        $data['lbl_cproduct']             = $this->m_language_key('cproduct');        $data['lbl_nquantity']            = $this->m_language_key('nquantity');        $data['lbl_fprice']               = $this->m_language_key('fprice');        $data['lbl_ftotal']               = $this->m_language_key('ftotal');        $data['lbl_fsum']                 = $this->m_language_key('fsum');        $data['lbl_vnd']                  = $this->m_language_key('vnd');        $data['cbo_order_status']         = $this->m_cbo_order_status;		$data['cbo_order_status_tt']    			= $this->m_cbo_order_status_tt;		$data['cbo_order_status_vc']    			= $this->m_cbo_order_status_vc;        $data['nid']                      = $this->m_nid;        $data['obj_order_view']           = $this->m_obj_order_view;        $data['obj_order_detail']         = Obj_get_order_detail_by_nid_order($this->m_nid);        $data['gencbo_order_status_list'] = Fgen_html_combobox('no', 'cbo_order_status', $this->m_cbo_order_status, '', $this->m_obj_order_status_view, 'nid', 'corder_status', 'nosubmit', '');		//$data['gencbo_order_status_tt_list']	= Fgen_html_combobox('no', 'cbo_order_status_tt', $this->m_cbo_order_status_tt, '', $this->m_obj_order_status_tt_view, 'nid', 'corder_status','nosubmit','');		//$data['gencbo_order_status_vc_list']	= Fgen_html_combobox('no', 'cbo_order_status_vc', $this->m_cbo_order_status_vc, '', $this->m_obj_order_status_vc_view, 'nid', 'corder_status','nosubmit','');        $data['menu_active']              = 'order';		$data['fr_img']              = Fstr_replace('admin/', '', base_url());        $this->load->view('order_view/index.php', $data);    }    private function destroy_data()    {    }    private function check_valid_not_null()    {        return TRUE;    }    private function check_valid_before_insert()    {        return TRUE;    }    private function insert_data()    {    }    private function check_valid_before_update()    {        return TRUE;    }    private function update_data()    {        if ($this->check_valid_before_update() == TRUE) {            $data = array(                'nid_order_status' => $this->m_cbo_order_status,				'nid_order_status_tt' => $this->m_cbo_order_status_tt,				'nid_order_status_vc' => $this->m_cbo_order_status_vc,                'niduser01' => $this->m_nid_user_login,                'cadmin_note' => $this->cadmin_note,				'cship' => $this->cship,				'cvat' => $this->cvat,				'cprice_sale_vnd' => $this->cprice_sale_vnd,				'caddress' => $this->caddress,				'cfullname' => $this->cfullname,				'nphone' => $this->nphone,				'cmst' => $this->cmst,				'cnote' => $this->cnote,                'ddate02' => dbget_current_date()            );						$this->m_obj_order_view   = $this->order_model->get_byid($this->m_nid);			$old_value = $this->m_obj_order_view['cship'] + $this->m_obj_order_view['cvat'] - $this->m_obj_order_view['cprice_sale_vnd'];			$new_value = $this->cship + $this->cvat - $this->cprice_sale_vnd;			//exit($old_value.'-'.$new_value);			$data['ntotal'] = $this->m_obj_order_view['ntotal'] - $old_value + $new_value;			            $this->order_model->update_bynid($this->m_nid, $data);            return TRUE;        } else {            return FALSE;        }    }}